// CanSSA reports whether values of type t can be represented as a Value.
func CanSSA(t *types.Type) bool {
	syncgoCtx := typeContextOf(t)
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	syncgoCtx.Types.CalcSize(t)
	if t.IsSIMD() {
		return true
	}
	if t.Size() == 0 {
		return true
	}
	sizeLimit := int64(MaxStruct * syncgoCtx.ptrSize)
	if t.Size() > sizeLimit {
		// 4*Widthptr is an arbitrary constant. We want it
		// to be at least 3*Widthptr so slices can be registerized.
		// Too big and we'll introduce too much register pressure.
		if !syncgoCtx.Types.Experiment.SIMD {
			return false
		}
	}
	switch t.Kind() {
	case types.TARRAY:
		// We can't do larger arrays because dynamic indexing is
		// not supported on SSA variables.
		// TODO: allow if all indexes are constant.
		if t.NumElem() <= 1 {
			return CanSSA(t.Elem())
		}
		return false
	case types.TSTRUCT:
		if syncgoCtx.Types.IsDirectIface(t) {
			// Note: even if t.NumFields()>MaxStruct! See issue 77534.
			return true
		}
		if t.NumFields() > MaxStruct {
			return false
		}
		for _, t1 := range t.Fields() {
			if !CanSSA(t1.Type) {
				return false
			}
		}
		// Special check for SIMD. If the composite type
		// contains SIMD vectors we can return true
		// if it pass the checks below.
		if !syncgoCtx.Types.Experiment.SIMD {
			return true
		}
		if t.Size() <= sizeLimit {
			return true
		}
		i, f := t.Registers()
		return i+f <= MaxStruct
	default:
		return true
	}
}
